<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import LegacyOptimizationRecords from './AiMaterialOptimizationRecordsView.vue';
import {withImageToken} from '../../api/tools/imageCropper.js';
import {shanghaiDateTimeText} from '../../utils/shanghai-date.js';
const route=useRoute(),router=useRouter(),source=ref(String(route.query.source||'all')),keyword=ref(''),rows=ref([]),loading=ref(false),errors=ref([]),detail=ref(null),drawer=ref(false),detailLoading=ref(false),legacyVisible=ref(Boolean(route.query.batchNo)),page=ref(1),pageSize=20;let sequence=0,detailSequence=0,disposed=false;
const sources=[{value:'all',label:'全部来源'},{value:'workflow',label:'AI模板工作流'},{value:'variant',label:'AI裂变'},{value:'optimization',label:'AI优化'},{value:'suite',label:'AI电商套图'},{value:'other',label:'其他生成'}];
const fieldNames={mainImage:'主图',detailImages:'详情图',commerceCopy:'商品文案',title:'标题',tags:'标签',description:'描述',video:'视频'};
const labels={queued:'排队中',running:'生成中',done:'已完成',completed:'已完成',success:'已完成',failed:'失败',cancelled:'已取消',awaiting_review:'待检查',ready:'可查看',partial:'部分完成'};
function classify(module=''){return /optimiz/.test(module)?'optimization':/variant_lab|fission/.test(module)?'variant':/ecommerce|suite/.test(module)?'suite':/workflow/.test(module)?'workflow':'other';}
const filtered=computed(()=>rows.value.filter(r=>(source.value==='all'||r.source===source.value)&&`${r.name} ${r.id}`.toLowerCase().includes(keyword.value.trim().toLowerCase())));
const paged=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize));
watch([source,keyword],()=>{page.value=1;});
async function load(){const seq=++sequence,scope=currentApiCacheScope();loading.value=true;const specs=[
 ['workflow','/api/product-workflows/runs',r=>({id:r.id,name:r.name,source:'workflow',kind:'workflow',status:r.draft_id?'done':'ready',time:r.updated_at||'',draftId:r.draft_id,record:r})],
 ['workflow','/api/product-workflows/job-states',r=>({id:r.run_id,kind:'job-status',status:r.status})],
 ['other','/api/material-assets?paged=1&pageSize=100&source_type=ai_generated',r=>({id:r.id,name:r.title||'AI图片',source:classify(r.source_module||r.source_type),kind:'asset',status:r.status||'ready',time:r.updated_at||r.created_at,record:r})],
 ['optimization','/api/product-workflows/optimizations',r=>({id:r.id,name:r.name,source:'optimization',kind:'optimization',status:r.payload.draftId?'done':'ready',time:r.updated_at,record:r})],
 ['variant','/api/ai-variant-lab/batch-jobs?limit=100',r=>({id:r.job_no,name:r.source_product_id||r.job_no,source:'variant',kind:'variant',status:r.status,time:r.updated_at,record:r})],
 ['optimization','/api/ai-material-optimization/batches',r=>({id:r.batch_no,name:r.batch_no,source:'optimization',kind:'legacy-optimization',status:r.status,time:r.created_at,record:r})],
 ['other','/api/ai-generation/tasks?limit=200',r=>({id:r.taskId,name:r.sourceProductId||fieldNames[r.fieldKey]||'生成内容',source:classify(r.sourceModule),kind:'task',status:r.status,time:r.createdAt,record:r})]
 ];try{const results=await Promise.allSettled(specs.map(async([,url,map])=>{const data=await apiClient.get(url,{noCache:true});return (Array.isArray(data)?data:(data.jobs||data.items||data.rows||[])).map(map);}));if(disposed||seq!==sequence||scope!==currentApiCacheScope())return;const all=results.flatMap(r=>r.status==='fulfilled'?r.value:[]);const states=new Map(all.filter(r=>r.kind==='job-status').map(r=>[r.id,r.status]));rows.value=all.filter(r=>r.kind!=='job-status').map(r=>r.kind==='workflow'&&!r.draftId?{...r,status:states.get(r.id)||r.status}:r).sort((a,b)=>new Date(b.time||0)-new Date(a.time||0));errors.value=results.flatMap((r,i)=>r.status==='rejected'?[`${sources.find(s=>s.value===specs[i][0])?.label||specs[i][0]}：${r.reason.message}`]:[]);}finally{if(seq===sequence)loading.value=false;}}
async function open(row){if(row.kind==='asset'){detail.value={row,data:{output:{generatedImages:[{url:row.record.url||row.record.publish_url||row.record.thumbnail_url}],description:row.record.content_text}}};drawer.value=true;return;}if(row.kind==='optimization')return router.push('/ai-product-material-optimizer?recordId='+encodeURIComponent(row.id));if(row.kind==='workflow')return router.push('/product-workflows?tab=results&runId='+encodeURIComponent(row.id));if(row.kind==='legacy-optimization'){await router.replace({query:{...route.query,batchNo:row.id}});legacyVisible.value=true;return;}drawer.value=true;detail.value=null;detailLoading.value=true;const seq=++detailSequence,scope=currentApiCacheScope();try{const url=row.kind==='variant'?'/api/ai-variant-lab/batch-jobs/'+encodeURIComponent(row.id)+'?full=1':'/api/ai-generation/tasks?taskIds='+encodeURIComponent(row.id)+'&includePayload=1';const data=await apiClient.get(url,{noCache:true});if(!disposed&&seq===detailSequence&&scope===currentApiCacheScope())detail.value={row,data:Array.isArray(data)?data[0]:data};}catch(e){ElMessage.error(e.message);}finally{if(seq===detailSequence)detailLoading.value=false;}}
const images=computed(()=>{const found=new Set();function walk(v){if(Array.isArray(v))return v.forEach(walk);if(!v||typeof v!=='object')return;for(const [key,value]of Object.entries(v)){if(['url','publishUrl','publish_url','previewUrl','imageUrl'].includes(key)&&typeof value==='string'&&/^(https?:|\/api\/|\/uploads\/)/.test(value))found.add(value);else if(!['input','source','analysis','original'].includes(key))walk(value);}}walk(detail.value?.data?.output||detail.value?.data?.result||detail.value?.data);return [...found];});
const copy=computed(()=>{const o=detail.value?.data?.output||{};return [o.title||o.titles?.[0],Array.isArray(o.tags)?o.tags.join(' '):o.tags,o.description].filter(Boolean).join('\n\n');});
function reset(){sequence++;detailSequence++;rows.value=[];detail.value=null;drawer.value=false;}
watch(()=>route.query.source,value=>{source.value=String(value||'all');});
onMounted(()=>{load();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>{disposed=true;reset();window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><main class="records"><header><h2>AI生成记录</h2><el-button :loading="loading" @click="load">刷新</el-button></header><div class="filters"><el-select v-model="source"><el-option v-for="s in sources" :key="s.value" :value="s.value" :label="s.label"/></el-select><el-input v-model="keyword" clearable placeholder="搜索名称或记录编号"/></div><el-alert v-for="message in errors" :key="message" :title="message" type="warning" :closable="false"/><el-table :data="paged" v-loading="loading" empty-text="暂无生成记录"><el-table-column label="来源" width="160"><template #default="{row}">{{sources.find(s=>s.value===row.source)?.label}}</template></el-table-column><el-table-column prop="name" label="名称／生成内容" min-width="220" show-overflow-tooltip/><el-table-column label="状态" width="120"><template #default="{row}">{{labels[row.status]||row.status}}</template></el-table-column><el-table-column label="时间（北京时间）" width="190"><template #default="{row}">{{row.time?shanghaiDateTimeText(row.time,{assumeUtcWhenNaive:true}):'未记录'}}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看结果</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="pageSize" :total="filtered.length" layout="total, prev, pager, next"/><p class="hint">展示各来源近期记录；历史任务的结果和处理入口保留。</p><el-drawer v-model="drawer" title="生成结果" size="70%"><div v-loading="detailLoading"><el-alert v-if="detail?.data?.error?.message" :title="detail.data.error.message" type="error"/><div class="images"><el-image v-for="url in images" :key="url" :src="withImageToken(url)" fit="contain" :preview-src-list="images.map(withImageToken)"/></div><p class="copy">{{copy}}</p><el-empty v-if="detail&&!images.length&&!copy" description="当前记录尚无可展示的图片或文案，请检查任务状态"/></div></el-drawer><el-dialog v-model="legacyVisible" title="历史优化任务" width="min(1300px,96vw)"><LegacyOptimizationRecords v-if="legacyVisible"/></el-dialog></main></template>
<style scoped>.records{padding:20px;max-width:1600px;margin:auto}header,.filters{display:flex;justify-content:space-between;gap:16px;margin-bottom:20px}.filters{justify-content:flex-start}.filters>.el-input{max-width:400px}.filters>.el-select{width:200px}.images{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px}.images>.el-image{height:300px}.copy{white-space:pre-wrap;line-height:1.8}.hint{color:var(--el-text-color-secondary);font-size:12px}.el-pagination{margin-top:20px}</style>
